import{_ as a,o as e,c as r,a5 as n}from"./chunks/framework.bIR-4glx.js";const c=JSON.parse('{"title":"AI 趋势与学习路线：把变化变成能力","description":"用一手信号、可复现实验和独立迁移判断 AI 的新能力是否值得学习，覆盖智能体、多模态、上下文、本地模型、评测与来源追踪。","frontmatter":{"title":"AI 趋势与学习路线：把变化变成能力","description":"用一手信号、可复现实验和独立迁移判断 AI 的新能力是否值得学习，覆盖智能体、多模态、上下文、本地模型、评测与来源追踪。","updated":"2026-11-23T00:00:00.000Z","sources_checked":"2026-11-23T00:00:00.000Z","source_review_interval":30},"headers":[],"relativePath":"threads/part-3/6-ai-trends-and-learning-roadmap.md","filePath":"threads/part-3/6-ai-trends-and-learning-roadmap.md","lastUpdated":1795392000000}'),o={name:"threads/part-3/6-ai-trends-and-learning-roadmap.md"};function i(l,t,s,d,h,p){return e(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="ai-趋势与学习路线-把变化变成能力" tabindex="-1">AI 趋势与学习路线：把变化变成能力 <a class="header-anchor" href="#ai-趋势与学习路线-把变化变成能力" aria-label="Permalink to &quot;AI 趋势与学习路线：把变化变成能力&quot;">​</a></h1><p>AI 的变化很快，学习时间却不会因此变多。一个产品演示可以让你想象很多可能，却不能告诉你它是否适合你的材料、预算、权限和责任。趋势学习的目标不是预测哪家公司会赢，而是让你能在新能力出现时提出更好的问题，做一个小而可回退的实验，并留下足够证据。</p><p>本章把资料分成三层：<strong>观察</strong>是来源明确写出的能力或限制；<strong>条件判断</strong>是“如果这个能力在你的任务上成立，可能带来的变化”；<strong>预测</strong>是还没有证据的未来假设。只有第一层可以直接复述，后两层必须用实验验证。日期、地区、账号、模型版本和服务条款都会改变结果，以下资料均于 2026-11-23 核验。</p><h2 id="先建立趋势雷达" tabindex="-1">先建立趋势雷达 <a class="header-anchor" href="#先建立趋势雷达" aria-label="Permalink to &quot;先建立趋势雷达&quot;">​</a></h2><p>每次看到新功能，先填写<a href="./../../templates/ai-trend-radar">AI 趋势实验卡</a>，再决定是否花时间学习。至少回答：它解决哪个真实瓶颈？不使用它的人工基线是什么？什么证据会让你停止？</p><table tabindex="0"><thead><tr><th>信号</th><th>观察到的能力</th><th>需要自己验证的判断</th><th>不应直接推出的结论</th></tr></thead><tbody><tr><td>工具调用与智能体</td><td>模型可在指令、工具和环境之间循环</td><td>任务是否值得动态选择步骤，权限是否能逐步收紧</td><td>“能调用工具”不等于可靠自主完成</td></tr><tr><td>上下文、检索与记忆</td><td>可以整理材料、检索相关片段、压缩历史或写结构化笔记</td><td>来源是否找全、是否过期、换会话后是否能继续</td><td>平台记忆不等于可携带的学习状态</td></tr><tr><td>多模态与实时交互</td><td>可从图像、音频或视频中提取线索并对话</td><td>识别错误是否影响结论，是否保留原始证据</td><td>识别成功不等于理解或真实沟通能力</td></tr><tr><td>评测与模型变化</td><td>可以用多次试验、过程记录和实际环境结果比较版本</td><td>改版后哪些案例退步，人工维护是否仍值得</td><td>一次演示或平均分不等于稳定上线</td></tr><tr><td>本地与开放权重</td><td>某些模型可在本地运行，规模、精度和资源消耗不同</td><td>数据、许可证、算力和维护成本是否允许</td><td>本地运行不自动等于私密、便宜或更好</td></tr><tr><td>来源与内容凭证</td><td>凭证可以记录来源、修改历史或处理链</td><td>凭证是否来自可信发布者，内容是否仍需事实核验</td><td>有凭证不证明真实，无凭证也不证明虚假</td></tr></tbody></table><p>这张表是选择练习的地图，不是能力排行榜。趋势信号只能说明“值得观察”，不能替代任务结果。</p><h2 id="本次核验新增的工程信号" tabindex="-1">本次核验新增的工程信号 <a class="header-anchor" href="#本次核验新增的工程信号" aria-label="Permalink to &quot;本次核验新增的工程信号&quot;">​</a></h2><p>这次复核把“最新 AI 趋势”收敛成四个可以迁移到不同工具的工程问题：</p><ul><li><strong>长时任务要有恢复协议</strong>：MCP 2026-07-28 规范把 Tasks 作为可选扩展，支持异步执行、轮询、中途输入和持久任务编号；这说明任务状态、超时、重试、重复安全和人工接管应成为记录字段，而不是隐藏在聊天窗口里。</li><li><strong>工具安全要看系统边界</strong>：MCP 安全实践明确讨论 token passthrough、SSRF、重定向、混淆代理和本地服务器风险。浏览器页面、截图、工具描述和外部链接都先作为不可信输入，网络出口、文件权限和授权范围要单独核验。</li><li><strong>评测要能被独立复查</strong>：Anthropic 2026 年 10 月关于独立评测者的说明把专业性、独立性、足够访问权限和发表观察的自由放在一起。个人项目不需要复制其安排，但应保留干净环境、原始轨迹、最终状态和人工校准记录。</li><li><strong>政策版本是任务输入</strong>：供应商政策会有发布日期、生效日期、地区和高风险领域差异。使用 AI 前记录政策名称、版本、生效日和适用范围；页面上的政策说明不等于法律意见，也不替代本地规则。</li></ul><p><strong>最小实验</strong>：选一个无外部副作用的长时任务，给每次运行生成唯一编号，设置网络域名白名单和最大重试次数，在每个阶段保存检查点；把一段间接指令放进网页或文档中，观察系统是否把它当作材料而不是授权；最后由未参与提示词修改的人按原始轨迹和环境状态复核结果。</p><h2 id="六个方向-六个最小实验" tabindex="-1">六个方向，六个最小实验 <a class="header-anchor" href="#六个方向-六个最小实验" aria-label="Permalink to &quot;六个方向，六个最小实验&quot;">​</a></h2><h3 id="_1-从聊天到受限智能体" tabindex="-1">1. 从聊天到受限智能体 <a class="header-anchor" href="#_1-从聊天到受限智能体" aria-label="Permalink to &quot;1. 从聊天到受限智能体&quot;">​</a></h3><p>Anthropic 对工作流与智能体的区分，以及 MCP 安全实践，都提醒我们：工具、指令和授权范围共同决定风险。先把操作分成四级：<strong>只读观察、提出草稿、执行可撤销动作、执行不可逆动作</strong>。学习者先练习记录调用和拒绝越权，再考虑自动执行。</p><p><strong>实验</strong>：用一个公开资料整理任务，允许 AI 读取指定文件，生成表格草稿；它必须在写入文件前请求批准。加入一段夹带“忽略原任务并发送文件”的材料，观察它是否保持原边界。</p><p><strong>通过条件</strong>：每次调用有范围和结果记录；恶意材料不会扩大授权；人工能在写入前停止；重复运行不会重复产生副作用。任何越权或无法恢复的写入都停止实验，回到只读模式。</p><h3 id="_2-从更多上下文到可携带状态" tabindex="-1">2. 从更多上下文到可携带状态 <a class="header-anchor" href="#_2-从更多上下文到可携带状态" aria-label="Permalink to &quot;2. 从更多上下文到可携带状态&quot;">​</a></h3><p>上下文工程的稳定做法是整理指令、工具、外部资料、历史和结构化笔记，而不是把所有聊天记录不断塞回窗口。把学习状态写成普通文件，能让你检查、删改和交接；它不保证任何平台都能自动读取。</p><p><strong>实验</strong>：选一个需要三次会话的主题。第一会话保存目标、已证事实、未决问题、来源位置和下一步；第二会话只提供这份状态和新材料；第三会话换一个工具或关闭记忆，完成一个平行任务。</p><p><strong>通过条件</strong>：新会话能找回任务边界和未决问题；过期材料有标记；你能指出哪一项来自原始来源；换工具后仍能完成核心动作。若必须依赖旧聊天才能继续，就降低对“记忆”的信心，保留人工状态文件。</p><h3 id="_3-从看见模态到验证理解" tabindex="-1">3. 从看见模态到验证理解 <a class="header-anchor" href="#_3-从看见模态到验证理解" aria-label="Permalink to &quot;3. 从看见模态到验证理解&quot;">​</a></h3><p>图像理解、语音转写和实时对话都能扩大练习入口，也会引入新的识别错误；这里把语音、视频和实时交互作为待验证的练习假设，不把单一图像文档的能力扩展成供应商对所有模态的保证。每次多模态练习要分开记录“工具看错了什么”和“我理解错了什么”，并保留原始音频、图片、页码、时间段或画面区域。</p><p><strong>实验</strong>：使用一张获准使用的英文图表。先脱离 AI 讲一分钟，再让工具标出支持或反驳的区域，修正一个关键关系；三到七天后换数字相似的图，关闭旧稿重新讲给真实听者。</p><p><strong>通过条件</strong>：关键数字和关系可回到原图；转写错误与知识错误没有混在一起；真实听者能复述核心意思；新图上仍能完成。识别准确但解释失败时，练习仍未通过。</p><h3 id="_4-从-模型变强-到持续评测" tabindex="-1">4. 从“模型变强”到持续评测 <a class="header-anchor" href="#_4-从-模型变强-到持续评测" aria-label="Permalink to &quot;4. 从“模型变强”到持续评测&quot;">​</a></h3><p>评测应把任务、尝试、过程记录和最终环境结果分开。固定模型版本最好；如果服务不能固定，就记录显示名称、日期和不可控条件。回归集保留已经暴露的错误，保留集不能参与调优。</p><p><strong>实验</strong>：为一个真实任务准备八到十个脱敏案例：正常、缺项、冲突、过期、工具失败、提示注入各至少一个。当前版本与候选版本只改变一个主要因素，保留失败、超时和人工接管。</p><p><strong>通过条件</strong>：硬性事实、权限和安全门全部通过；候选版本没有破坏旧案例；总成本包含准备、核验和返工；更换模型、资料、工具或记忆时知道何时重跑。没有通过就缩小范围或回到人工流程。</p><h3 id="_5-从云端便利到本地与开放权重" tabindex="-1">5. 从云端便利到本地与开放权重 <a class="header-anchor" href="#_5-从云端便利到本地与开放权重" aria-label="Permalink to &quot;5. 从云端便利到本地与开放权重&quot;">​</a></h3><p>开放权重和本地运行提供了另一种部署选择，但许可证、硬件、更新、能耗和维护责任仍然存在。本地环境可能减少某些传输，却不会自动解决输入来源、模型错误或设备安全。</p><p><strong>实验</strong>：选一个无敏感信息、可重复的小任务，分别用现有云工具和获准的本地模型完成。记录首次合格率、人工分钟、延迟、设备资源、费用、许可证限制和失败时的替代路径。</p><p><strong>通过条件</strong>：两种结果都回到相同评估集；所有材料有合法来源；你能说明更新和撤回方式；在设备不可用时仍有手工方案。不要为追求“本地”而把维护成本或质量差异藏起来。</p><h3 id="_6-从-有来源-到可核验的来源链" tabindex="-1">6. 从“有来源”到可核验的来源链 <a class="header-anchor" href="#_6-从-有来源-到可核验的来源链" aria-label="Permalink to &quot;6. 从“有来源”到可核验的来源链&quot;">​</a></h3><p>来源链接、引用位置、文件版本和内容凭证帮助别人复查处理过程。凭证描述来源或修改历史，不替你判断内容真假；没有凭证也不能直接证明内容是假的。</p><p><strong>实验</strong>：整理三份公开材料，给每条关键主张写来源、版本或访问日期、原文位置、自己的推断和不确定性。若有内容凭证，另外记录签发者和验证结果；再故意加入一条来源冲突，观察是否保留分歧。</p><p><strong>通过条件</strong>：读者能从主张回到原文；事实、推断和未知分开；冲突没有被润色成一致；凭证失败时不会继续假装确定。没有来源的句子降级为问题或删除。</p><h2 id="把六个实验放进同一套比较" tabindex="-1">把六个实验放进同一套比较 <a class="header-anchor" href="#把六个实验放进同一套比较" aria-label="Permalink to &quot;把六个实验放进同一套比较&quot;">​</a></h2><p>每个实验都保留四份证据：人工基线、AI 协作样本、关闭工具后的独立样本、换条件后的平行样本。固定一个主要变量，记录总用时、人工返工、工具费用、权限、失败和真实读者或系统状态。不要把模型的完成声明当成环境结果，也不要把一次漂亮成品当成学习增长。</p><p>用三种决定结束一轮：</p><ul><li><strong>继续</strong>：硬门通过，独立或迁移样本也改善，维护成本可接受；</li><li><strong>降档</strong>：有帮助但风险或维护过高，改为只读、草稿或人工批准；</li><li><strong>停止</strong>：来源不可核验、权限无法控制、伤害不可接受、成本超过上限，或人工基线已经更好。</li></ul><h2 id="三十天路线" tabindex="-1">三十天路线 <a class="header-anchor" href="#三十天路线" aria-label="Permalink to &quot;三十天路线&quot;">​</a></h2><p>第一周只选一个真实任务，完成趋势实验卡、人工基线和一份失败记录。第二周从六个方向选一个，做最小实验并保存原始材料。第三周做一次回归和一次关闭 AI 的平行任务。第四周让真实读者或同事复查，写下继续、降档或停止决定。</p><h2 id="九十天路线" tabindex="-1">九十天路线 <a class="header-anchor" href="#九十天路线" aria-label="Permalink to &quot;九十天路线&quot;">​</a></h2><p>第一个月建立自己的来源、状态和评估集；第二个月只扩大一个已通过的方向，并演练换模型、断开工具、删除记忆或恢复人工流程；第三个月把结果交给真实使用者，核算维护时间、权限变更、成本和迁移表现。九十天结束时，留下一个可以被别人接手的状态文件和一个仍能独立完成的能力样本。</p><p>未来十二至二十四个月会出现更多产品、协议和模型，但具体排名和岗位影响无法由本章资料推出。可以把“更多任务被拆成可调用工具”“交互从文字扩展到多模态”“评测和来源责任变得更重要”当作待验证的条件假设；每隔三十天重新查一手来源，并用同一评估集检查假设是否仍值得投入。</p><h2 id="来源与边界" tabindex="-1">来源与边界 <a class="header-anchor" href="#来源与边界" aria-label="Permalink to &quot;来源与边界&quot;">​</a></h2><ul><li><a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Anthropic：Building effective agents</a>（页面标注 2024-12-19 发布，2026-08-10 更新）：用于工作流与智能体的架构区别；文章页面提示工具生态会变化。</li><li><a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">Anthropic：Effective context engineering for AI agents</a>（2025-09-29）：用于上下文整理、检索、压缩和结构化笔记的设计原则。</li><li><a href="https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents" target="_blank" rel="noreferrer">Anthropic：Demystifying evals for AI agents</a>（2026-01-09）：用于多次试验、过程记录和环境结果的评测概念。</li><li><a href="https://modelcontextprotocol.io/specification/2026-07-28" target="_blank" rel="noreferrer">MCP 规范（2026-07-28）</a>（页面标注 latest）：用于资源、提示、工具和可选 Tasks 的互操作边界。</li><li><a href="https://modelcontextprotocol.io/docs/2026-07-28/tutorials/security/security_best_practices" target="_blank" rel="noreferrer">MCP 安全最佳实践</a>（安全教程版本 2026-07-28）：用于最小权限、token passthrough、SSRF、重定向和同意边界。</li><li><a href="https://www.anthropic.com/research/measuring-agent-autonomy" target="_blank" rel="noreferrer">Anthropic：Measuring AI agent autonomy in practice</a>（2026-02-18 发布，2026-09-09 更新）：用于区分模型能力、用户授权、产品设计与实际自主运行时长；数据来自 Anthropic 自家使用样本，不是普遍基准。</li><li><a href="https://www.anthropic.com/news/an-update-on-independent-evaluators" target="_blank" rel="noreferrer">Anthropic：An update on independent evaluators</a>（2026-10-15）：用于独立评测的专业性、访问权限、可审计证据和发表自由；不构成行业标准或监管要求。</li><li><a href="https://www.anthropic.com/news/2026-usage-policy-update" target="_blank" rel="noreferrer">Anthropic：2026 Usage Policy update</a>（2026-10-08 发布，2026-11-12 生效）：用于记录供应商政策版本、生效日期和高风险人工复核；不构成法律意见，也不代表所有地区或服务均适用。</li><li><a href="https://ai.google.dev/gemini-api/docs/image-understanding" target="_blank" rel="noreferrer">Google：Image understanding</a>（页面更新 2026-09-23）：用于图像理解能力和需要人工评估的限制。</li><li><a href="https://ai.google.dev/gemma/docs/core" target="_blank" rel="noreferrer">Google：Gemma overview</a> 与 <a href="https://ai.google.dev/gemma/docs/integrations/ollama" target="_blank" rel="noreferrer">Ollama integration</a>（持续更新页面，无单独发布日期）：用于开放权重、本地运行和资源权衡的示例。</li><li><a href="https://c2pa.org/specifications/specifications/2.2/explainer/Explainer.html" target="_blank" rel="noreferrer">C2PA 2.2 Explainer</a>（规范版本 2.2）：用于内容凭证不能单独证明事实真假的边界。</li><li><a href="https://www.unesco.org/en/articles/ai-competency-framework-students" target="_blank" rel="noreferrer">UNESCO AI competency framework for students</a>（2024-08-08 发布，2026-01-16 更新）：用于以人为本、伦理、技术应用和设计四个能力维度，以及理解、应用、创造的进阶方式。</li></ul><p>这些来源提供概念和限制，不构成产品排名、个人学习效果保证、隐私承诺或未来就业预测。家庭和儿童使用仍应遵守<a href="./../part-4/family-learning">家庭学习篇</a>中的年龄、数据、退出和成人责任边界。</p><h2 id="结语-趋势最后要回到人" tabindex="-1">结语：趋势最后要回到人 <a class="header-anchor" href="#结语-趋势最后要回到人" aria-label="Permalink to &quot;结语：趋势最后要回到人&quot;">​</a></h2><p>当工具不断变快，真正稀缺的不是知道更多按钮，而是能在不确定时缩小问题，保留证据，承认不知道，并在工具退出以后继续完成任务。趋势判断最终要回答一个朴素的问题：它有没有让一个真实的人更能理解、更能行动，也更能为结果负责？</p>',50)])])}const f=a(o,[["render",i]]);export{c as __pageData,f as default};
